fn is_happy(s: Vec<char>) -> bool {
    // A happy sequence must have at least 3 characters.
    if s.len() < 3 {
        return false;
    }

    // Check each consecutive block of three characters.
    // They must all be pairwise distinct.
    for i in 0..(s.len() - 2) {
        let a = s[i];
        let b = s[i + 1];
        let c = s[i + 2];
        if a == b || a == c || b == c {
            return false;
        }
    }

    true
}

